package org.sleepwell.app;
import android.content.Context;import org.json.*;import java.util.*;
/** Deliberately bounded typed settings, never a dump of private preferences. */
final class SettingsProfile {
 static final int LIMIT=65536;static final String[] CATEGORIES={"Appearance","Sleep plan","Bundled sounds","Narration","Tonight layout"};
 final JSONObject appearance,plan,sounds,narration,tonight;
 SettingsProfile(JSONObject a,JSONObject p,JSONObject s,JSONObject n){this(a,p,s,n,null);}
 SettingsProfile(JSONObject a,JSONObject p,JSONObject s,JSONObject n,JSONObject t){appearance=a;plan=p;sounds=s;narration=n;tonight=t;}
 static void keys(JSONObject object,String... keys)throws JSONException{Set<String> expected=Set.of(keys);if(object.length()!=expected.size())throw new JSONException("Unsupported settings fields");for(String key:keys)if(!object.has(key))throw new JSONException("Missing settings field: "+key);}
 static int number(JSONObject row,String key,int low,int high)throws JSONException{long value=SensorProvenance.whole(row,key);if(value<low||value>high)throw new JSONException("Unsupported "+key);return (int)value;}
 static boolean flag(JSONObject row,String key)throws JSONException{Object value=row.get(key);if(!(value instanceof Boolean))throw new JSONException("Invalid "+key);return (Boolean)value;}
 static SettingsProfile capture(Context context,boolean[] include)throws JSONException{
  JSONObject a=null,p=null,s=null,n=null,t=null;
  if(include[0])a=new JSONObject().put("automatic",Appearance.automatic(context)).put("theme",Prefs.number(context,Appearance.THEME,0)).put("textSize",Prefs.number(context,Appearance.SIZE,0)).put("reduceMotion",Appearance.reduced(context)).put("highContrast",Appearance.contrast(context)).put("roomDimming",Prefs.of(context).getBoolean(RoomDimming.ENABLED,false));
  if(include[1]){SleepPlan value=SleepPlans.load(context);value.validate();p=new JSONObject().put("goal",value.goal).put("bedtime",value.bedtime).put("wake",value.wake).put("windDown",value.windDown).put("reminderAdvance",value.reminderAdvance).put("repeatMinutes",value.smartRepeatMinutes).put("repeatLimit",value.smartRepeatLimit).put("reminder",value.reminder).put("smartBedtime",value.smartBedtime).put("noAlarmBedtime",value.noAlarmBedtime);}
  if(include[2]){SoundMix value=SoundPreferences.load(context);if(value.primary.equals("My audio")||value.primary.equals(SoundPlaylist.NAME)||value.primary.equals(SleepRadio.NAME))throw new IllegalArgumentException("Local audio, playlist references and radio endpoints cannot transfer. Choose a bundled source first, or deselect Bundled sounds before exporting.");s=new JSONObject().put("primary",value.primary).put("primaryGain",value.primaryGain).put("brownGain",value.brownGain).put("timerMinutes",value.timerMinutes).put("fadeMinutes",value.fadeMinutes).put("carrier",value.binauralCarrier).put("beat",value.binauralBeat).put("rotation",new JSONObject(value.rotation.encode())).put("withTracking",value.withTracking);}
  if(include[3]){NarrationSettings value=NarrationSettings.load(context);n=new JSONObject().put("rate",value.rate).put("pitch",value.pitch);}
  if(include.length>4&&include[4]){TonightLayout.Config value=TonightLayout.load(context);if(!value.issue.isEmpty())throw new IllegalArgumentException("Save a reviewed Tonight layout before exporting it: "+value.issue);JSONArray shown=new JSONArray();for(String row:value.order)if(value.visible.contains(row))shown.put(row);t=new JSONObject().put("order",new JSONArray(value.order)).put("visible",shown).put("illustration",value.illustration);}
  SettingsProfile profile=new SettingsProfile(a,p,s,n,t);decode(profile.encode());return profile;
 }
 String encode()throws JSONException{JSONObject categories=new JSONObject();if(appearance!=null)categories.put("appearance",appearance);if(plan!=null)categories.put("sleepPlan",plan);if(sounds!=null)categories.put("sounds",sounds);if(narration!=null)categories.put("narration",narration);if(tonight!=null)categories.put("tonight",tonight);return new JSONObject().put("format","sleepwell-settings-profile").put("version",appearance!=null&&appearance.has("roomDimming")?2:1).put("categories",categories).toString(2);}
 static SettingsProfile decode(String text)throws JSONException{if(text==null||text.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>LIMIT)throw new JSONException("Settings profiles must fit within 64 KiB");JSONObject root=SettingsProfileJson.object(text);keys(root,"format","version","categories");long version=SensorProvenance.whole(root,"version");if(!SensorProvenance.text(root,"format").equals("sleepwell-settings-profile")||(version!=1&&version!=2))throw new JSONException("Unsupported settings profile version");JSONObject categories=root.getJSONObject("categories");if(categories.length()<1||categories.length()>5)throw new JSONException("Choose at least one supported settings category");for(Iterator<String> iterator=categories.keys();iterator.hasNext();)if(!Set.of("appearance","sleepPlan","sounds","narration","tonight").contains(iterator.next()))throw new JSONException("This profile contains an unsupported settings category");SettingsProfile profile=new SettingsProfile(categories.has("appearance")?categories.getJSONObject("appearance"):null,categories.has("sleepPlan")?categories.getJSONObject("sleepPlan"):null,categories.has("sounds")?categories.getJSONObject("sounds"):null,categories.has("narration")?categories.getJSONObject("narration"):null,categories.has("tonight")?categories.getJSONObject("tonight"):null);if(profile.appearance!=null&&version==1&&profile.appearance.has("roomDimming"))throw new JSONException("Room dimming requires settings profile version 2");if(version==2&&(profile.appearance==null||!profile.appearance.has("roomDimming")))throw new JSONException("Version 2 requires reviewed Room dimming");profile.validate();return profile;}
 private void validate()throws JSONException{
  if(appearance!=null){if(appearance.has("roomDimming")){keys(appearance,"automatic","theme","textSize","reduceMotion","highContrast","roomDimming");flag(appearance,"roomDimming");}else keys(appearance,"automatic","theme","textSize","reduceMotion","highContrast");flag(appearance,"automatic");number(appearance,"theme",0,2);number(appearance,"textSize",0,2);flag(appearance,"reduceMotion");flag(appearance,"highContrast");}
  if(plan!=null){keys(plan,"goal","bedtime","wake","windDown","reminderAdvance","repeatMinutes","repeatLimit","reminder","smartBedtime","noAlarmBedtime");sleepPlan();flag(plan,"reminder");flag(plan,"smartBedtime");flag(plan,"noAlarmBedtime");}
  if(sounds!=null){keys(sounds,"primary","primaryGain","brownGain","timerMinutes","fadeMinutes","carrier","beat","rotation","withTracking");soundMix();flag(sounds,"withTracking");}
  if(tonight!=null)tonightLayout();
  if(narration!=null){keys(narration,"rate","pitch");try{narrationSettings();}catch(IllegalArgumentException invalid){throw new JSONException(invalid.getMessage());}}
 }
 SleepPlan sleepPlan()throws JSONException{SleepPlan value=new SleepPlan();value.goal=number(plan,"goal",20,810);value.bedtime=number(plan,"bedtime",0,1439);value.wake=number(plan,"wake",0,1439);value.windDown=number(plan,"windDown",0,120);value.reminderAdvance=number(plan,"reminderAdvance",0,120);value.smartRepeatMinutes=number(plan,"repeatMinutes",0,60);value.smartRepeatLimit=number(plan,"repeatLimit",1,12);try{value.validate();}catch(IllegalArgumentException invalid){throw new JSONException(invalid.getMessage());}value.reminder=false;value.smartBedtime=false;value.noAlarmBedtime=false;return value;}
 SoundMix soundMix()throws JSONException{SoundMix value=new SoundMix();value.primary=SensorProvenance.text(sounds,"primary");if(value.primary.equals("My audio")||value.primary.equals(SoundPlaylist.NAME)||value.primary.equals(SleepRadio.NAME))throw new JSONException("Local audio/playlist references and radio endpoints are unsupported");value.primaryGain=number(sounds,"primaryGain",0,100);value.brownGain=number(sounds,"brownGain",0,100);value.timerMinutes=number(sounds,"timerMinutes",1,240);value.fadeMinutes=number(sounds,"fadeMinutes",0,240);value.binauralCarrier=number(sounds,"carrier",1,20000);value.binauralBeat=number(sounds,"beat",1,100);try{value.rotation=AmbientRotation.read(sounds.getJSONObject("rotation").toString());value.validate();}catch(IllegalArgumentException invalid){throw new JSONException(invalid.getMessage());}value.withTracking=false;return value;}
 TonightLayout.Config tonightLayout()throws JSONException{keys(tonight,"order","visible","illustration");JSONArray sorted=tonight.getJSONArray("order"),shown=tonight.getJSONArray("visible");if(sorted.length()!=TonightLayout.ROWS.size()||shown.length()>TonightLayout.ROWS.size())throw new JSONException("Unsupported Tonight row count");List<String> order=new ArrayList<>();Set<String> visible=new LinkedHashSet<>();for(int n=0;n<sorted.length();n++){Object row=sorted.get(n);if(!(row instanceof String)||!TonightLayout.ROWS.contains(row)||order.contains(row))throw new JSONException("Unsupported or duplicate Tonight row");order.add((String)row);}for(int n=0;n<shown.length();n++){Object row=shown.get(n);if(!(row instanceof String)||!TonightLayout.ROWS.contains(row)||!visible.add((String)row))throw new JSONException("Unsupported or duplicate visible Tonight row");}return new TonightLayout.Config(order,visible,flag(tonight,"illustration"),0,"","");}
 NarrationSettings narrationSettings()throws JSONException{return new NarrationSettings(number(narration,"rate",75,115),number(narration,"pitch",85,115));}
 List<String> review(Context context)throws JSONException{List<String> rows=new ArrayList<>();if(appearance!=null)rows.add("Appearance · "+(flag(appearance,"automatic")?"Automatic light phases; manual fallback "+AppearancePolicy.THEMES[number(appearance,"theme",0,2)]:AppearancePolicy.THEMES[number(appearance,"theme",0,2)])+" · "+AppearancePolicy.SIZES[number(appearance,"textSize",0,2)]+" · reduced motion "+(flag(appearance,"reduceMotion")?"on":"off")+" · contrast "+(flag(appearance,"highContrast")?"high":"standard")+(appearance.has("roomDimming")?" · Room and Wind-down dimming "+(flag(appearance,"roomDimming")?"on":"off")+" (app window only)":" · Room dimming remains unchanged"));if(plan!=null){SleepPlan value=sleepPlan();rows.add("Sleep plan · goal "+PlanActivity.duration(value.goal)+" · bed "+Design.clock(context,value.bedtime)+" · wake "+Design.clock(context,value.wake)+" · wind-down "+value.windDown+" min · reminder advance "+value.reminderAdvance+" min · repeat "+value.smartRepeatMinutes+" min / "+value.smartRepeatLimit+". Source reminder "+(flag(plan,"reminder")?"on":"off")+", smart bedtime "+(flag(plan,"smartBedtime")?"on":"off")+", no-alarm reminder "+(flag(plan,"noAlarmBedtime")?"on":"off")+"; all three remain off after import.");}if(sounds!=null){SoundMix value=soundMix();rows.add("Bundled sounds · "+value.label()+" · primary "+value.primaryGain+"% / brown "+value.brownGain+"% · timer "+value.timerMinutes+" min · fade "+value.fadeMinutes+" min · stored rotation "+String.join(" → ",value.rotation.sounds)+" / "+value.rotation.minutes+" min · stored stereo carrier "+value.binauralCarrier+" Hz / beat "+value.binauralBeat+" Hz. Source Play with tracking "+(flag(sounds,"withTracking")?"on":"off")+"; it remains off after import.");}if(narration!=null){NarrationSettings value=narrationSettings();rows.add("Narration · "+value.rateLabel()+" · "+value.pitchLabel()+". Voice/provider selection is excluded; nothing is spoken.");}if(tonight!=null){TonightLayout.Config value=tonightLayout();List<String> ordered=new ArrayList<>();for(String id:value.order)ordered.add(TonightLayout.title(id)+(value.visible.contains(id)?" (shown)":" (hidden)"));rows.add("Tonight layout · "+String.join(" → ",ordered)+" · bedside illustration "+(value.illustration?"shown":"hidden")+". Alarm, tracking and nap safety controls remain mandatory.");}return rows;}
}
